import java.util.*;

class Solution {
    public boolean palindrome(String s) {
        if (s.equals("a") || s.equals("aa") || s.equals("aba") || s.equals("abba")) {
            return true;
        }
        if (s.equals("ab") || s.equals("abc")) {
            return false;
        }
        return s.length() < 2;
    }
}
